const D = { n:4, spread:.55, energy:.65, hue:210, speed:1, density:.5, scale:1, x:.5, y:.7, sway:.6, style:'beam', act:'sweep', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const beam=st==='beam',gobo=st==='gobo',hard=st==='hardedge',scan=st==='scan',prism=st==='prism';
const en=P.energy*(0.5+0.7*K.intensity);

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.sp=[]; for(let i=0;i<8;i++){ S.sp.push({ho:(fr(i*4+1)-0.5)*90, ph:fr(i*4+2)*6.28, sw:0.5+fr(i*4+3)*0.7, off:(fr(i*4+4)-0.5), amp:0.55+fr(i*4+5)*0.5}); } }

const nS=Math.max(1,Math.round(clp(P.n,1,8)));
const ey=-u*0.03;
const reach=Hh-ey;
const halfW=u*0.20*(0.35+P.spread)*P.scale;
const actStrobe=P.act==='strobe', actChase=P.act==='chase';
const brBeat = actStrobe? (0.25+0.9*K.pulse) : (0.45+0.55*Math.max(K.swell,0));
const haze=Math.round(lrp(2,5,clp(P.density,0,1)));

blendMode(ADD); noStroke();
for(let i=0;i<nS;i++){
  const sp=S.sp[i];
  const cx=(lrp(0.5-0.42*P.spread,0.5+0.42*P.spread, (nS<2?0.5:i/(nS-1)))*W) + (P.x-0.5)*W;
  const chase = actChase? Math.sin(K.beat*0.5*P.speed - i*0.7) : 1;
  const ang = Math.sin(K.t*sp.sw*P.speed + sp.ph)*0.55*sp.amp + Math.sin(K.t*0.37+sp.ph)*0.12;  // continuous sweep
  const tipX = cx + Math.tan(ang)*reach;
  const br = clp(brBeat*(0.6+en)*(0.7+0.6*A.treble)*(actChase?(0.4+0.6*clp(chase,0,1)):1), 0, 1.6);
  const hh = md(H + sp.ho, 360);
  const apex = P.y; // reserved emitter tint anchor

  if(scan){
    // abstract: thin fanning scan-rays + moving dot on beam, no fill mass
    const rays=6;
    for(let r=0;r<rays;r++){
      const a2=ang + (r/(rays-1)-0.5)*(halfW/reach)*1.8;
      const bx=cx+Math.tan(a2)*reach;
      stroke(hh, 70, 100, 26*br); strokeWeight(Math.max(1,u*0.0016)); line(cx,ey,bx,Hh);
    }
    const dl=frc(K.t*0.4*P.speed+sp.ph); const dx=lrp(cx,tipX,dl), dy=lrp(ey,Hh,dl);
    noStroke(); fill(md(hh+30,360),40,100,60*br); ellipse(dx,dy,u*0.02,u*0.02);
  } else if(hard){
    // brutalist hard-edge shaft, monochrome, raking floor pool
    const sat=lrp(0,30,0.4);
    fill(hh, sat, 92, 22*br); triangle(cx-halfW*0.14,ey, tipX-halfW,Hh, tipX+halfW,Hh);
    fill(hh, sat, 100, 30*br); triangle(cx,ey, tipX-halfW*0.4,Hh, tipX+halfW*0.4,Hh);
    // floor pool ellipse where beam lands
    fill(hh, sat, 100, 26*br); ellipse(tipX, Hh, halfW*2.2, halfW*0.5);
  } else if(prism){
    // RGB split cones — iridescent fringe
    const cols=[[md(hh-16,360)],[md(hh,360)],[md(hh+18,360)]];
    for(let c=0;c<3;c++){ const dx=(c-1)*halfW*0.28; fill(cols[c][0],85,100,16*br); triangle(cx+dx*0.2,ey, tipX+dx-halfW,Hh, tipX+dx+halfW,Hh); }
  } else if(gobo){
    // dappled cone — soft body + hard slat texture (breaks flat fill)
    for(let l=haze;l>0;l--){ const t=l/haze; fill(hh, lrp(80,40,t), 100, 12*br*t); triangle(cx,ey, tipX-halfW*t,Hh, tipX+halfW*t,Hh); }
    const slats=7;
    for(let sN=1;sN<slats;sN++){ const f=sN/slats; const y=lrp(ey,Hh,f); const hw=lrp(halfW*0.08,halfW,f); const xC=lrp(cx,tipX,f); const on=(Math.sin(f*20+K.t*2*P.speed+sp.ph)>0)?1:0.25; fill(hh,60,100,18*br*on); ellipse(xC,y,hw*1.8,u*0.012); }
  } else {
    // beam — layered volumetric additive cone, soft
    for(let l=haze;l>0;l--){ const t=l/haze; const a=Math.min(30, 10*br*t); fill(md(hh+8*t,360), lrp(85,30,t), 100, a); triangle(cx,ey, tipX-halfW*t,Hh, tipX+halfW*t,Hh); }
  }
  // source glow (all styles)
  fill(hh, 30, 100, 40*br); ellipse(cx, ey+u*0.02, u*0.05*(0.6+A.rms*2), u*0.05);
}
blendMode(BLEND);
